values.headerSass:
.custom-header {
  /* NavBar */



#nav-bloc {
  margin-top: 30px;
}

.navbar{
	margin-bottom: 0;
}
.navbar-brand{
	  cursor:pointer;
  text-decoration: none;
  padding-bottom:0.05em;
  border-bottom: none;

}
.navbar-brand img{
	width: 147px;
	height: 70px;
	margin: -12px 5px 0 0;
}
.navbar-brand{
	padding: 15px 15px;
}
.navbar .nav{
	padding-top: 2px;
	margin-right: -16px;
	float:right;
}
.nav > li{
	float: left;
	margin-top: 4px;
	font-size: 16px;
}
.nav > li a:hover{
	background:transparent;
}
.navbar-toggle{
	margin: 12px;
	border: 0px;
}
.navbar-toggle:hover{
	background:transparent!important;
}
.navbar-toggle .icon-bar{
	background-color: #706f6f;
	width: 26px;
}
.navbar-collapse.in {
overflow-y: visible;
float: left;
width: 100%;
}
.navbar-1 {
  float: right;
}
.site-navigation:first-child {
  float: left;
}
.site-navigation:nth-child(2) {
  float: right;
}
.site-navigation:nth-child(2) a {
  color: #706f6f;
  font-size: 85%;
  padding-right: 0px;
}

.site-navigation .nav > .active{
  color: #706f6f;
  background-color:#f5f5f5 !important;
}

.site-navigation .nav > li{
  color: #706f6f;
  background-color:#f5f5f5 !important;
}



.btn-min-block {
    min-width: 170px;
    line-height: 26px;
}

.btn-theme {
    color: #706f6f;
    background-color: transparent;
    border-color: #fff;
    margin-right: 15px;
    -webkit-border-radius: 0px;
    -moz-border-radius: 0px;
    border-radius: 0px;
}

.btn-theme:hover {
    color: #706f6f;
    background-color: transparent;
    border-color: #706f6f;
}






/* Mobile adjustments */

@media (max-width: 768px)
{
    .bloc{
        text-align: center;
        -webkit-background-size: auto 200%;
        -moz-background-size: auto 200%;
        -o-background-size: auto 200%;
        background-size: auto 200%;
    }
    .navbar .nav{
        padding-top: 0;
        border-top:1px solid rgba(0,0,0,.2);
        float:none!important;
    }
    .nav > li{
        margin-top: 0;
        border-bottom:1px solid rgba(0,0,0,.1);
        background:rgba(0,0,0,.05);
        text-align: left;
        width:100%;
    }
    .nav > li:hover{
        background:rgba(0,0,0,.08);
    }
    .navbar-collapse{
        -webkit-box-shadow: none;
        box-shadow: none;
    }
    .btn.pull-left, .btn.pull-right{
       float:none!important; 
    }
    .bloc-xl,.bloc-lg{
        padding: 40px 0;
    }
    .a-block{
        text-align: center;
    }
}

a {
  font-size:16px;
  color:#706f6f;
  font-family: Discount_RS;
  letter-spacing:3px;
  text-decoration: none;

}


.head_links:hover {
  text-decoration: none;
  background-color: #f5f5f5;
  font-size:16px;
  color:#706f6f;
  padding-bottom:0.05em;
  border-bottom: 0.15em solid #706f6f;
  cursor: pointer;
}

.head_links:visited {
text-decoration: none;
  background-color: #f5f5f5;
  font-size:16px;
  color:#706f6f;

}

.whitelink, .whitelink:visited, .whitelink:active, .whitelink:hover {
  text-decoration: none;
   cursor: pointer;
}

.logo_class, .logo_class:visited, .logo_class:active, .logo_class:hover {
  cursor:pointer;
  text-decoration: none;
  padding-bottom:0.05em;
  border-bottom: none;

}

h1 {
font-size:32px;
color:#3979a7;
font-family: Discount_M; 
letter-spacing:4px;
display:inline;

}

  }

